msg.payload = {
  service: "Node-RED lab2",
  version: "1.0.0"
};
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
return msg;

// Забираем path-параметр id
const idRaw = msg.req.params.id;
const id = parseInt(idRaw, 10);

// Забираем query-параметр limit (по умолчанию 10)
const limitRaw = msg.req.query.limit || "10";
const limit = parseInt(limitRaw, 10);

// Проверка id: должен быть числом > 0
if (isNaN(id) || id <= 0) {
    msg.statusCode = 400;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    msg.payload = {
        error: "Invalid id",
        message: "id должен быть положительным числом",
        received: idRaw
    };
    return msg;
}

// Проверка limit: если задан, должен быть числом от 1 до 50
if (isNaN(limit) || limit < 1 || limit > 50) {
    msg.statusCode = 400;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    msg.payload = {
        error: "Invalid limit",
        message: "limit должен быть числом от 1 до 50",
        received: limitRaw
    };
    return msg;
}

// Товара с таким id нет (у нас всего 100)
if (id > 100) {
    msg.statusCode = 404;
    msg.headers = { "Content-Type": "application/json; charset=utf-8" };
    msg.payload = {
        error: "Not found",
        message: `Товар с id=${id} не найден`,
        maxId: 100
    };
    return msg;
}

// Успех: отдаём товар и список похожих
const items = [];
for (let i = 0; i < limit; i++) {
    items.push({
        id: id * 100 + i,
        name: `Товар #${id}-${i}`,
        price: +(Math.random() * 1000).toFixed(2)
    });
}

msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
msg.payload = {
    requestedId: id,
    limit: limit,
    count: items.length,
    items: items
};
return msg;
